package com.flippingfriend.companion;
import org.junit.Test; import static org.junit.Assert.*;
public class BuyReplacementKellyFractionEvaluatorTest {
 @Test public void appliesProductionFractionFloorAndCeilingInOrder(){BuyReplacementKellySizingInputContext s=source();BuyReplacementKellyFractionEvaluationSet r=new BuyReplacementKellyFractionEvaluator().evaluate(s,1100);assertNotNull(r);assertEquals(s.getInputs().size(),r.getEvaluations().size());for(int i=0;i<r.getEvaluations().size();i++){BuyReplacementKellySizingInput a=s.getInputs().get(i);BuyReplacementKellyFractionEvaluation e=r.getEvaluations().get(i);assertEquals(CandidateFactory.kellyFraction(a.getCompletionProbability(),a.getPayoffOdds()),e.getKellyFraction(),0.0);assertEquals(a.getBuyOffsetIndex(),e.getBuyOffsetIndex());assertEquals(a.getExpectedProfit(),e.getExpectedProfit(),0.0);assertEquals(a.getWorstLoss(),e.getWorstLoss());}try{r.getEvaluations().clear();fail("immutable");}catch(UnsupportedOperationException expected){}}
 @Test public void unavailableAndStaleInputsFailClosed(){BuyReplacementKellyFractionEvaluator e=new BuyReplacementKellyFractionEvaluator();assertNull(e.evaluate(null,1100));assertNull(e.evaluate(source(),1221));}
 @Test public void contractsCarryNoQuantityGridGenerationScoringSelectionOrAuthorization()throws Exception{for(String f:new String[]{"BuyReplacementKellyFractionEvaluation.java","BuyReplacementKellyFractionEvaluationSet.java"}){String x=java.nio.file.Files.readString(java.nio.file.Path.of("src/main/java/com/flippingfriend/companion/"+f));for(String forbidden:new String[]{"Math.round","expectedGpPerSlotHour","selected","score","rank","PortfolioCandidate","PolicyDecision","OfferLifecycleAction","REPLACEMENT_AUTHORIZED"})assertFalse(x.contains(forbidden));}}
 static BuyReplacementKellyFractionEvaluationSet evaluationSetForCompanionTests(){return new BuyReplacementKellyFractionEvaluator().evaluate(source(),1100);} private static BuyReplacementKellySizingInputContext source(){return BuyReplacementKellySizingInputContextComposerTest.kellyEvaluationContextForCompanionTests();}
}
